window.PP_DATA={"version":"2.1","conceptCount":138,"questions":[{"id":"V21-D001","concept":1,"topic":"Principles","subtopic":"Continued business justification","question":"Which PRINCE2 principle requires a project to remain desirable, viable and achievable throughout its life?","answer":"Ensure continued business justification","options":["Manage by exception","Focus on products","Ensure continued business justification","Learn from experience"],"explanation":"A PRINCE2 project needs a valid reason to start and to continue. If justification disappears, continuation must be reconsidered.","learningPoint":"A PRINCE2 project needs a valid reason to start and to continue. If justification disappears, continuation must be reconsidered."},{"id":"V21-D002","concept":2,"topic":"Principles","subtopic":"Learn from experience","question":"Which principle requires teams to seek, record and apply lessons?","answer":"Learn from experience","options":["Tailor to suit the project","Learn from experience","Manage by stages","Focus on products"],"explanation":"Lessons should be sought at the start, captured during the project and applied throughout.","learningPoint":"Lessons should be sought at the start, captured during the project and applied throughout."},{"id":"V21-D003","concept":3,"topic":"Principles","subtopic":"Roles","question":"Which principle makes accountability and stakeholder representation explicit?","answer":"Define roles, responsibilities and relationships","options":["Define roles, responsibilities and relationships","Manage by exception","Focus on products","Ensure continued business justification"],"explanation":"Projects need clear accountability, responsibilities and relationships.","learningPoint":"Projects need clear accountability, responsibilities and relationships."},{"id":"V21-D004","concept":4,"topic":"Principles","subtopic":"Stages","question":"Which principle divides a project into manageable sections for planning and control?","answer":"Manage by stages","options":["Tailor to suit the project","Learn from experience","Focus on products","Manage by stages"],"explanation":"PRINCE2 plans, monitors and controls work stage by stage.","learningPoint":"PRINCE2 plans, monitors and controls work stage by stage."},{"id":"V21-D005","concept":5,"topic":"Principles","subtopic":"Exception","question":"Which principle delegates authority within defined limits?","answer":"Manage by exception","options":["Focus on products","Learn from experience","Manage by exception","Manage by stages"],"explanation":"Tolerance limits enable delegated authority; forecast breaches are escalated.","learningPoint":"Tolerance limits enable delegated authority; forecast breaches are escalated."},{"id":"V21-D006","concept":6,"topic":"Principles","subtopic":"Products","question":"Which principle emphasizes defining what must be delivered before deciding activities?","answer":"Focus on products","options":["Manage by exception","Focus on products","Manage by stages","Learn from experience"],"explanation":"Product focus clarifies expectations and reduces scope creep and rework.","learningPoint":"Product focus clarifies expectations and reduces scope creep and rework."},{"id":"V21-D007","concept":7,"topic":"Principles","subtopic":"Tailoring","question":"Which principle requires the method to be adapted to project context?","answer":"Tailor to suit the project","options":["Tailor to suit the project","Manage by exception","Focus on products","Learn from experience"],"explanation":"PRINCE2 should be applied appropriately rather than mechanically.","learningPoint":"PRINCE2 should be applied appropriately rather than mechanically."},{"id":"V21-D008","concept":8,"topic":"People","subtopic":"People","question":"PRINCE2 7 places which element at the centre of the method?","answer":"People","options":["Technology","Procurement","Contracts","People"],"explanation":"PRINCE2 7 explicitly recognizes people as central to successful projects.","learningPoint":"PRINCE2 7 explicitly recognizes people as central to successful projects."},{"id":"V21-D009","concept":9,"topic":"People","subtopic":"Adoption","question":"Why should a project consider the people affected by project outputs?","answer":"Because outputs create value only when people adopt and use the resulting change","options":["Because people replace the business case","Because only users own all risks","Because outputs create value only when people adopt and use the resulting change","Because users authorize every stage"],"explanation":"Benefits depend on successful adoption and use, not merely delivery of outputs.","learningPoint":"Benefits depend on successful adoption and use, not merely delivery of outputs."},{"id":"V21-D010","concept":10,"topic":"People","subtopic":"Stakeholders","question":"What is the main purpose of stakeholder engagement?","answer":"To understand and influence relationships, expectations and support","options":["To authorize all work packages","To understand and influence relationships, expectations and support","To replace Project Assurance","To remove tolerances"],"explanation":"Stakeholder engagement improves alignment, decisions, support and adoption.","learningPoint":"Stakeholder engagement improves alignment, decisions, support and adoption."},{"id":"V21-D011","concept":11,"topic":"People","subtopic":"Communication","question":"What should a communication management approach primarily define?","answer":"How, when and with whom project communications will take place","options":["How, when and with whom project communications will take place","How quality tests are executed","How risk exposure is calculated","How stage tolerances are set"],"explanation":"It defines how the project will communicate with stakeholders.","learningPoint":"It defines how the project will communicate with stakeholders."},{"id":"V21-D012","concept":12,"topic":"People","subtopic":"Leadership","question":"Which statement best distinguishes leadership from management?","answer":"Leadership influences and motivates; management organizes and controls","options":["Leadership belongs only to the Executive","Management is only about finance","PRINCE2 treats them as identical","Leadership influences and motivates; management organizes and controls"],"explanation":"Projects need both leadership and management.","learningPoint":"Projects need both leadership and management."},{"id":"V21-D013","concept":13,"topic":"People","subtopic":"Culture","question":"Why should organizational culture be considered?","answer":"It can affect behaviour, collaboration, decisions and adoption","options":["It replaces governance","It removes the need for planning","It can affect behaviour, collaboration, decisions and adoption","It sets the exam pass mark"],"explanation":"Culture can materially influence project behaviour and change adoption.","learningPoint":"Culture can materially influence project behaviour and change adoption."},{"id":"V21-D014","concept":14,"topic":"Business case","subtopic":"Purpose","question":"What is the purpose of the business case practice?","answer":"To judge whether the project is and remains desirable, viable and achievable","options":["To record daily progress","To judge whether the project is and remains desirable, viable and achievable","To allocate work packages","To define quality methods only"],"explanation":"The business case practice supports continued business justification.","learningPoint":"The business case practice supports continued business justification."},{"id":"V21-D015","concept":15,"topic":"Business case","subtopic":"Executive","question":"Who is ultimately accountable for the business case?","answer":"Executive","options":["Executive","Project Manager","Senior User","Team Manager"],"explanation":"The Executive owns the business viewpoint and is accountable for the business case.","learningPoint":"The Executive owns the business viewpoint and is accountable for the business case."},{"id":"V21-D016","concept":16,"topic":"Business case","subtopic":"Benefits","question":"Which Project Board role represents those who use products and realize benefits?","answer":"Senior User","options":["Senior Supplier","Executive","Project Support","Senior User"],"explanation":"The Senior User represents user interests and benefit realization.","learningPoint":"The Senior User represents user interests and benefit realization."},{"id":"V21-D017","concept":17,"topic":"Business case","subtopic":"Benefits approach","question":"Which management product defines how and when benefits will be measured?","answer":"Benefits management approach","options":["Quality register","Daily log","Benefits management approach","Risk register"],"explanation":"The benefits management approach defines benefit measurement activities and responsibilities.","learningPoint":"The benefits management approach defines benefit measurement activities and responsibilities."},{"id":"V21-D018","concept":18,"topic":"Business case","subtopic":"Loss of justification","question":"What should happen if a project can no longer be justified?","answer":"Escalate it and consider premature closure","options":["Transfer accountability to the Team Manager","Escalate it and consider premature closure","Continue until the stage ends regardless","Increase every tolerance"],"explanation":"A project should not continue without valid business justification.","learningPoint":"A project should not continue without valid business justification."},{"id":"V21-D019","concept":19,"topic":"Business case","subtopic":"Options","question":"Why compare alternative business options?","answer":"To compare different ways of achieving the desired outcome and value","options":["To compare different ways of achieving the desired outcome and value","To eliminate user involvement","To avoid documenting assumptions","To replace benefits measurement"],"explanation":"Options analysis helps determine whether the proposed project offers worthwhile value.","learningPoint":"Options analysis helps determine whether the proposed project offers worthwhile value."},{"id":"V21-D020","concept":20,"topic":"Organizing","subtopic":"Project Board","question":"Which body provides overall direction and management of the project?","answer":"Project Board","options":["Project Support","Delivery Team","Change Authority only","Project Board"],"explanation":"The Project Board is accountable for project success and provides overall direction.","learningPoint":"The Project Board is accountable for project success and provides overall direction."},{"id":"V21-D021","concept":21,"topic":"Organizing","subtopic":"Executive","question":"Which Project Board role is ultimately accountable for the project?","answer":"Executive","options":["Senior Supplier","Project Manager","Executive","Senior User"],"explanation":"The Executive chairs the board and balances business, user and supplier interests.","learningPoint":"The Executive chairs the board and balances business, user and supplier interests."},{"id":"V21-D022","concept":22,"topic":"Organizing","subtopic":"Senior User","question":"Which role represents those who will use the project's products?","answer":"Senior User","options":["Project Assurance","Senior User","Senior Supplier","Executive"],"explanation":"The Senior User represents user needs and expected benefits.","learningPoint":"The Senior User represents user needs and expected benefits."},{"id":"V21-D023","concept":23,"topic":"Organizing","subtopic":"Senior Supplier","question":"Which role represents those designing or supplying specialist products?","answer":"Senior Supplier","options":["Senior Supplier","Senior User","Executive","Project Support"],"explanation":"The Senior Supplier represents supplier interests and technical integrity.","learningPoint":"The Senior Supplier represents supplier interests and technical integrity."},{"id":"V21-D024","concept":24,"topic":"Organizing","subtopic":"Project Manager","question":"Who manages the project day to day within board constraints?","answer":"Project Manager","options":["Executive","Senior User","Project Support","Project Manager"],"explanation":"The Project Manager is responsible for day-to-day management.","learningPoint":"The Project Manager is responsible for day-to-day management."},{"id":"V21-D025","concept":25,"topic":"Organizing","subtopic":"Team Manager","question":"Who manages production of products allocated in a work package?","answer":"Team Manager","options":["Project Manager","Project Assurance","Team Manager","Executive"],"explanation":"A Team Manager accepts and delivers work packages.","learningPoint":"A Team Manager accepts and delivers work packages."},{"id":"V21-D026","concept":26,"topic":"Organizing","subtopic":"Project Assurance","question":"What is the purpose of Project Assurance?","answer":"To independently check that the project is being conducted properly and remains viable","options":["To replace the Project Board","To independently check that the project is being conducted properly and remains viable","To perform all administration","To approve every team plan"],"explanation":"Project Assurance gives the board confidence that the project is being managed appropriately.","learningPoint":"Project Assurance gives the board confidence that the project is being managed appropriately."},{"id":"V21-D027","concept":27,"topic":"Organizing","subtopic":"Project Support","question":"What is a typical Project Support responsibility?","answer":"Administrative, tool, configuration and information support","options":["Administrative, tool, configuration and information support","Owning the business case","Authorizing closure","Representing benefits on the board"],"explanation":"Project Support assists management with administration and specialist support.","learningPoint":"Project Support assists management with administration and specialist support."},{"id":"V21-D028","concept":28,"topic":"Plans","subtopic":"Purpose","question":"What is the purpose of the plans practice?","answer":"To facilitate communication and control by defining how products will be delivered","options":["To decide whether a risk has occurred","To appoint the Executive","To close issues automatically","To facilitate communication and control by defining how products will be delivered"],"explanation":"Plans define what will be delivered, how, when, by whom and at what cost.","learningPoint":"Plans define what will be delivered, how, when, by whom and at what cost."},{"id":"V21-D029","concept":29,"topic":"Plans","subtopic":"Product-based planning","question":"What is defined first in product-based planning?","answer":"The required products","options":["Supplier invoices","Issue priorities","The required products","Detailed activities"],"explanation":"Product-based planning starts by identifying and defining required products.","learningPoint":"Product-based planning starts by identifying and defining required products."},{"id":"V21-D030","concept":30,"topic":"Plans","subtopic":"Project plan","question":"Which plan provides the high-level view of the whole project?","answer":"Project plan","options":["Daily log","Project plan","Team plan","Exception plan"],"explanation":"The project plan provides the overall project-level view.","learningPoint":"The project plan provides the overall project-level view."},{"id":"V21-D031","concept":31,"topic":"Plans","subtopic":"Stage plan","question":"Which plan contains detail for managing a management stage?","answer":"Stage plan","options":["Stage plan","Project brief","Issue report","Benefits management approach"],"explanation":"Stage plans support day-to-day control by the Project Manager.","learningPoint":"Stage plans support day-to-day control by the Project Manager."},{"id":"V21-D032","concept":32,"topic":"Plans","subtopic":"Team plan","question":"Which plan may a Team Manager use for detailed work package delivery?","answer":"Team plan","options":["Project plan","Business case","Exception report","Team plan"],"explanation":"A team plan supports detailed team-level work.","learningPoint":"A team plan supports detailed team-level work."},{"id":"V21-D033","concept":33,"topic":"Plans","subtopic":"Exception plan","question":"When is an exception plan produced?","answer":"When a plan is forecast to exceed tolerance and a replacement plan is requested","options":["After every checkpoint report","Only at closure","When a plan is forecast to exceed tolerance and a replacement plan is requested","At the start of every project"],"explanation":"An exception plan replaces the plan forecast to go into exception.","learningPoint":"An exception plan replaces the plan forecast to go into exception."},{"id":"V21-D034","concept":34,"topic":"Plans","subtopic":"Product description","question":"What does a product description define?","answer":"Purpose, composition, quality specifications and quality methods for a product","options":["Stage authorization decisions","Purpose, composition, quality specifications and quality methods for a product","The full organization chart","All project risks"],"explanation":"Product descriptions clarify expectations for individual products.","learningPoint":"Product descriptions clarify expectations for individual products."},{"id":"V21-D035","concept":35,"topic":"Plans","subtopic":"Project product description","question":"What does the project product description define?","answer":"The major final product and its acceptance criteria","options":["The major final product and its acceptance criteria","Every work package","All lessons","Stage tolerances only"],"explanation":"It anchors expectations for the project's overall output and acceptance.","learningPoint":"It anchors expectations for the project's overall output and acceptance."},{"id":"V21-D036","concept":36,"topic":"Quality","subtopic":"Purpose","question":"What is the purpose of the quality practice?","answer":"To ensure products are fit for purpose and meet stated requirements","options":["To guarantee zero risk","To authorize stages","To define supplier contracts","To ensure products are fit for purpose and meet stated requirements"],"explanation":"Quality planning and control ensure products meet agreed expectations.","learningPoint":"Quality planning and control ensure products meet agreed expectations."},{"id":"V21-D037","concept":37,"topic":"Quality","subtopic":"Quality planning","question":"What should exist before quality control begins?","answer":"Clear quality specifications and acceptance criteria","options":["A closure notification","A supplier invoice","Clear quality specifications and acceptance criteria","An exception report"],"explanation":"You need defined expectations before assessing product quality.","learningPoint":"You need defined expectations before assessing product quality."},{"id":"V21-D038","concept":38,"topic":"Quality","subtopic":"Quality control","question":"What is quality control concerned with?","answer":"Inspecting or testing products against quality specifications","options":["Setting business tolerance","Inspecting or testing products against quality specifications","Deciding whether the project is justified","Appointing the Project Board"],"explanation":"Quality control checks actual products against defined requirements.","learningPoint":"Quality control checks actual products against defined requirements."},{"id":"V21-D039","concept":39,"topic":"Quality","subtopic":"Quality assurance","question":"How does quality assurance differ from Project Assurance?","answer":"Quality assurance is organizational and focuses on the quality system","options":["Quality assurance is organizational and focuses on the quality system","They are identical","Quality assurance belongs only to the Team Manager","Project Assurance checks invoices only"],"explanation":"Quality assurance is generally independent of the project management team; Project Assurance is a project governance responsibility.","learningPoint":"Quality assurance is generally independent of the project management team; Project Assurance is a project governance responsibility."},{"id":"V21-D040","concept":40,"topic":"Quality","subtopic":"Acceptance criteria","question":"What do acceptance criteria describe?","answer":"Measurable conditions the final product must satisfy to be accepted","options":["Risk exposure limits","Board meeting dates","Checkpoint formats","Measurable conditions the final product must satisfy to be accepted"],"explanation":"Acceptance criteria provide the basis for acceptance of the project product.","learningPoint":"Acceptance criteria provide the basis for acceptance of the project product."},{"id":"V21-D041","concept":41,"topic":"Quality","subtopic":"Quality register","question":"What is recorded in the quality register?","answer":"Planned and completed quality activities and their results","options":["All risk response costs","Every benefit","Planned and completed quality activities and their results","All stakeholders"],"explanation":"The quality register records quality control activities.","learningPoint":"The quality register records quality control activities."},{"id":"V21-D042","concept":42,"topic":"Risk","subtopic":"Definition","question":"What is a risk in PRINCE2?","answer":"An uncertain event or set of events that could affect objectives","options":["A mandatory change request","An uncertain event or set of events that could affect objectives","A problem that has definitely happened","A failed quality test only"],"explanation":"Risk concerns uncertainty and can be a threat or an opportunity.","learningPoint":"Risk concerns uncertainty and can be a threat or an opportunity."},{"id":"V21-D043","concept":43,"topic":"Risk","subtopic":"Opportunity","question":"A risk that could have a beneficial effect is called what?","answer":"Opportunity","options":["Opportunity","Threat","Exception","Issue"],"explanation":"PRINCE2 recognizes both threats and opportunities.","learningPoint":"PRINCE2 recognizes both threats and opportunities."},{"id":"V21-D044","concept":44,"topic":"Risk","subtopic":"Risk owner","question":"Who is accountable for managing, monitoring and controlling a particular risk?","answer":"Risk owner","options":["Risk action owner","Project Support","Senior Supplier automatically","Risk owner"],"explanation":"The risk owner is accountable for an assigned risk.","learningPoint":"The risk owner is accountable for an assigned risk."},{"id":"V21-D045","concept":45,"topic":"Risk","subtopic":"Risk action owner","question":"Who carries out a specific risk response action?","answer":"Risk action owner","options":["Project Assurance","Senior User","Risk action owner","Executive"],"explanation":"The risk action owner performs agreed response actions.","learningPoint":"The risk action owner performs agreed response actions."},{"id":"V21-D046","concept":46,"topic":"Risk","subtopic":"Risk register","question":"Where are identified risks normally recorded?","answer":"Risk register","options":["Issue report","Risk register","Quality register","Product register"],"explanation":"The risk register is the primary record of identified risks.","learningPoint":"The risk register is the primary record of identified risks."},{"id":"V21-D047","concept":47,"topic":"Risk","subtopic":"Avoid","question":"Which threat response removes the threat so it can no longer affect the project?","answer":"Avoid","options":["Avoid","Exploit","Enhance","Share"],"explanation":"Avoid changes the situation so the threat no longer affects objectives.","learningPoint":"Avoid changes the situation so the threat no longer affects objectives."},{"id":"V21-D048","concept":48,"topic":"Risk","subtopic":"Exploit","question":"Which opportunity response aims to make sure the opportunity happens?","answer":"Exploit","options":["Avoid","Reduce","Transfer","Exploit"],"explanation":"Exploit is used when the project wants to ensure an opportunity is realized.","learningPoint":"Exploit is used when the project wants to ensure an opportunity is realized."},{"id":"V21-D049","concept":49,"topic":"Risk","subtopic":"Reduce","question":"Which threat response lowers probability and/or impact?","answer":"Reduce","options":["Enhance","Share","Reduce","Exploit"],"explanation":"Reduce lowers likelihood or effect.","learningPoint":"Reduce lowers likelihood or effect."},{"id":"V21-D050","concept":50,"topic":"Issues","subtopic":"Purpose","question":"What is the purpose of the issues practice?","answer":"To collect and assess issues and control changes to baselines","options":["To remove all uncertainty","To collect and assess issues and control changes to baselines","To calculate exam results","To appoint suppliers"],"explanation":"The issues practice provides structured handling of concerns, problems and changes.","learningPoint":"The issues practice provides structured handling of concerns, problems and changes."},{"id":"V21-D051","concept":51,"topic":"Issues","subtopic":"Issue","question":"Which best describes an issue?","answer":"An event relevant to the project that has happened and needs consideration","options":["An event relevant to the project that has happened and needs consideration","An uncertain future event only","A plan always within tolerance","A quality method"],"explanation":"Unlike a risk, an issue concerns something that has happened or is current.","learningPoint":"Unlike a risk, an issue concerns something that has happened or is current."},{"id":"V21-D052","concept":52,"topic":"Issues","subtopic":"Change control","question":"Why is change control important?","answer":"To assess proposed changes before altering baselines","options":["To approve every request","To stop user feedback","To avoid updating plans","To assess proposed changes before altering baselines"],"explanation":"Changes require impact assessment and controlled decisions.","learningPoint":"Changes require impact assessment and controlled decisions."},{"id":"V21-D053","concept":53,"topic":"Issues","subtopic":"Baseline","question":"What is a baseline?","answer":"An approved version of a product subject to change control","options":["Only the business case","A verbal instruction","An approved version of a product subject to change control","Any draft"],"explanation":"Baselines provide stable reference points for control.","learningPoint":"Baselines provide stable reference points for control."},{"id":"V21-D054","concept":54,"topic":"Issues","subtopic":"Issue register","question":"What is the issue register used for?","answer":"To maintain information about formal issues requiring management","options":["To replace the business case","To maintain information about formal issues requiring management","To schedule quality tests only","To record lessons only"],"explanation":"The issue register provides a controlled record of issues.","learningPoint":"The issue register provides a controlled record of issues."},{"id":"V21-D055","concept":55,"topic":"Issues","subtopic":"Change Authority","question":"What is the purpose of a Change Authority?","answer":"To decide specified changes within delegated limits","options":["To decide specified changes within delegated limits","To manage all teams","To replace the Executive","To provide quality assurance"],"explanation":"The Project Board may delegate authority for specified changes.","learningPoint":"The Project Board may delegate authority for specified changes."},{"id":"V21-D056","concept":56,"topic":"Progress","subtopic":"Purpose","question":"What is the purpose of the progress practice?","answer":"To monitor achievement, forecast performance and control deviations","options":["To define the Project Board","To create specialist products","To negotiate all contracts","To monitor achievement, forecast performance and control deviations"],"explanation":"Progress provides mechanisms for monitoring, forecasting and control.","learningPoint":"Progress provides mechanisms for monitoring, forecasting and control."},{"id":"V21-D057","concept":57,"topic":"Progress","subtopic":"Tolerance","question":"What does tolerance represent?","answer":"Permitted deviation from a plan before escalation is required","options":["Minimum suppliers","Quality test method","Permitted deviation from a plan before escalation is required","Maximum risks allowed"],"explanation":"Tolerance enables management by exception.","learningPoint":"Tolerance enables management by exception."},{"id":"V21-D058","concept":58,"topic":"Progress","subtopic":"Exception","question":"When does an exception situation arise?","answer":"When it is forecast that tolerance will be exceeded","options":["At every stage boundary","When it is forecast that tolerance will be exceeded","Whenever a checkpoint is late","Whenever any risk is identified"],"explanation":"Escalation is based on a forecast tolerance breach.","learningPoint":"Escalation is based on a forecast tolerance breach."},{"id":"V21-D059","concept":59,"topic":"Progress","subtopic":"Highlight report","question":"Which report does the Project Manager normally send to the Project Board at agreed intervals?","answer":"Highlight report","options":["Highlight report","Checkpoint report","End stage report","Issue report"],"explanation":"Highlight reports keep the Project Board informed.","learningPoint":"Highlight reports keep the Project Board informed."},{"id":"V21-D060","concept":60,"topic":"Progress","subtopic":"Checkpoint report","question":"Which report is typically produced by a Team Manager for the Project Manager?","answer":"Checkpoint report","options":["Highlight report","Exception report","End project report","Checkpoint report"],"explanation":"Checkpoint reports provide regular team-level progress information.","learningPoint":"Checkpoint reports provide regular team-level progress information."},{"id":"V21-D061","concept":61,"topic":"Progress","subtopic":"End stage report","question":"Which report summarizes performance of a management stage?","answer":"End stage report","options":["Work package","Project brief","End stage report","Daily log"],"explanation":"The end stage report supports assessment at a stage boundary.","learningPoint":"The end stage report supports assessment at a stage boundary."},{"id":"V21-D062","concept":62,"topic":"Progress","subtopic":"Exception report","question":"What should the Project Manager produce when tolerance is forecast to be exceeded?","answer":"Exception report","options":["Lessons log only","Exception report","Checkpoint report","Product description"],"explanation":"An exception report informs the Project Board and supports a decision.","learningPoint":"An exception report informs the Project Board and supports a decision."},{"id":"V21-D063","concept":63,"topic":"Progress","subtopic":"Daily log","question":"What is the daily log primarily used for?","answer":"Informal notes and events that do not need separate formal registers","options":["Informal notes and events that do not need separate formal registers","Authorizing stages","Replacing the risk register","Approving the business case"],"explanation":"The daily log acts as an informal diary.","learningPoint":"The daily log acts as an informal diary."},{"id":"V21-D064","concept":64,"topic":"Processes","subtopic":"Starting up a Project","question":"What is the purpose of Starting up a Project?","answer":"To determine whether the project is worthwhile and viable enough to initiate","options":["To deliver all specialist products","To authorize closure","To manage stage exceptions","To determine whether the project is worthwhile and viable enough to initiate"],"explanation":"Starting up avoids committing major resources before basic viability is understood.","learningPoint":"Starting up avoids committing major resources before basic viability is understood."},{"id":"V21-D065","concept":65,"topic":"Processes","subtopic":"Project brief","question":"Which product is developed in Starting up a Project to support the initiation decision?","answer":"Project brief","options":["Exception plan","Checkpoint report","Project brief","End project report"],"explanation":"The project brief provides a foundation for deciding whether to initiate.","learningPoint":"The project brief provides a foundation for deciding whether to initiate."},{"id":"V21-D066","concept":66,"topic":"Processes","subtopic":"Directing a Project","question":"Which process is used by the Project Board for key decisions and overall control?","answer":"Directing a Project","options":["Starting up a Project","Directing a Project","Controlling a Stage","Managing Product Delivery"],"explanation":"Directing a Project is the board-level process.","learningPoint":"Directing a Project is the board-level process."},{"id":"V21-D067","concept":67,"topic":"Processes","subtopic":"Initiating a Project","question":"What is the main purpose of Initiating a Project?","answer":"To establish solid foundations before major commitment","options":["To establish solid foundations before major commitment","To close the project","To create team plans only","To perform every quality test"],"explanation":"Initiating develops the detailed basis for managing the project.","learningPoint":"Initiating develops the detailed basis for managing the project."},{"id":"V21-D068","concept":68,"topic":"Processes","subtopic":"PID","question":"Which management product brings together key information needed to direct and manage the project?","answer":"Project initiation documentation (PID)","options":["Checkpoint report","Issue report","Product register","Project initiation documentation (PID)"],"explanation":"The PID consolidates the project's management foundations and baselines.","learningPoint":"The PID consolidates the project's management foundations and baselines."},{"id":"V21-D069","concept":69,"topic":"Processes","subtopic":"Controlling a Stage","question":"Which process is used by the Project Manager for day-to-day management of a stage?","answer":"Controlling a Stage","options":["Starting up a Project","Closing a Project","Controlling a Stage","Directing a Project"],"explanation":"Controlling a Stage covers work authorization, monitoring, issues and reporting.","learningPoint":"Controlling a Stage covers work authorization, monitoring, issues and reporting."},{"id":"V21-D070","concept":70,"topic":"Processes","subtopic":"Managing Product Delivery","question":"Which process manages the Team Manager side of accepting and delivering work packages?","answer":"Managing Product Delivery","options":["Closing a Project","Managing Product Delivery","Initiating a Project","Directing a Project"],"explanation":"Managing Product Delivery controls the team-side work package interface.","learningPoint":"Managing Product Delivery controls the team-side work package interface."},{"id":"V21-D071","concept":71,"topic":"Processes","subtopic":"Managing a Stage Boundary","question":"Which process reviews the current stage and prepares for the next-stage decision?","answer":"Managing a Stage Boundary","options":["Managing a Stage Boundary","Starting up a Project","Managing Product Delivery","Controlling a Stage"],"explanation":"It reviews performance, updates information and prepares the next stage plan.","learningPoint":"It reviews performance, updates information and prepares the next stage plan."},{"id":"V21-D072","concept":72,"topic":"Processes","subtopic":"Closing a Project","question":"What is the purpose of Closing a Project?","answer":"To confirm acceptance and evaluate project performance at a fixed point","options":["To authorize initiation","To assign new work packages","To identify the Executive","To confirm acceptance and evaluate project performance at a fixed point"],"explanation":"Closing confirms acceptance and provides orderly closure.","learningPoint":"Closing confirms acceptance and provides orderly closure."},{"id":"V21-D073","concept":73,"topic":"Sustainability","subtopic":"Performance","question":"PRINCE2 7 explicitly includes which consideration among project performance targets?","answer":"Sustainability","options":["Office location","Certification renewal","Sustainability","Advertising"],"explanation":"PRINCE2 7 highlights sustainability alongside traditional project performance considerations.","learningPoint":"PRINCE2 7 highlights sustainability alongside traditional project performance considerations."},{"id":"V21-D074","concept":74,"topic":"Digital and data","subtopic":"Approach","question":"What should a digital and data management approach address?","answer":"How project data and digital information are created, used, protected and managed","options":["Only product acceptance","How project data and digital information are created, used, protected and managed","Only board meeting dates","Only risk responses"],"explanation":"PRINCE2 7 recognizes digital and data management as an important project consideration.","learningPoint":"PRINCE2 7 recognizes digital and data management as an important project consideration."},{"id":"V21-D075","concept":75,"topic":"Digital and data","subtopic":"Decision quality","question":"Why is good project data important?","answer":"It supports reliable reporting, forecasting, decisions and control","options":["It supports reliable reporting, forecasting, decisions and control","It eliminates all risks","It removes the need for people","It makes tailoring unnecessary"],"explanation":"Reliable data supports reliable project decisions.","learningPoint":"Reliable data supports reliable project decisions."},{"id":"V21-D076","concept":76,"topic":"Tailoring","subtopic":"Small project","question":"How should PRINCE2 be tailored on a small, low-risk project?","answer":"Simplify the method while preserving principles and necessary controls","options":["Skip all principles","Remove business justification","Use maximum documentation detail","Simplify the method while preserving principles and necessary controls"],"explanation":"Tailoring adjusts formality and detail without abandoning the method's intent.","learningPoint":"Tailoring adjusts formality and detail without abandoning the method's intent."},{"topic":"Principles","subtopic":"Continued business justification","question":"A project remains technically feasible, but updated forecasts show that expected benefits no longer justify the remaining cost. Which principle requires this situation to be addressed?","answer":"Ensure continued business justification","options":["Learn from experience","Focus on products","Manage by stages","Ensure continued business justification"],"explanation":"A PRINCE2 project must have a valid business reason to start and to continue.","learningPoint":"If justification disappears, do not continue merely because work has already begun.","id":"V21-S001","concept":1001},{"topic":"Principles","subtopic":"Learn from experience","question":"At project start, the Project Manager reviews lessons from a similar project and changes the new project approach. Which principle is being applied?","answer":"Learn from experience","options":["Tailor to suit the project","Learn from experience","Focus on products","Manage by exception"],"explanation":"PRINCE2 expects lessons to be sought and applied throughout the project.","learningPoint":"Seek lessons early, capture new ones, and pass them on.","id":"V21-S002","concept":1002},{"topic":"Principles","subtopic":"Roles","question":"A project has strong supplier representation, but nobody is clearly accountable for representing the people who will use the products. Which principle is not being applied adequately?","answer":"Define roles, responsibilities and relationships","options":["Focus on products","Define roles, responsibilities and relationships","Manage by stages","Manage by exception"],"explanation":"Business, user and supplier interests need clear representation and accountability.","learningPoint":"Project roles are about accountability, not job titles.","id":"V21-S003","concept":1003},{"topic":"Principles","subtopic":"Stages","question":"The Project Board authorizes only the next portion of work after reviewing current performance and the updated business case. Which principle is demonstrated?","answer":"Manage by stages","options":["Manage by stages","Learn from experience","Focus on products","Manage by exception"],"explanation":"Management stages provide control points for review and authorization.","learningPoint":"Stage boundaries let the Board decide whether to continue before committing further resources.","id":"V21-S004","concept":1004},{"topic":"Principles","subtopic":"Exception","question":"A stage is forecast to finish two days late, which remains inside the time tolerance delegated to the Project Manager. What should normally happen?","answer":"The Project Manager should continue to manage the stage without escalating solely because of the delay","options":["The stage should be stopped","The Project Board should take over daily management","The Project Manager should continue to manage the stage without escalating solely because of the delay","An exception report must be sent immediately"],"explanation":"Tolerance defines the limits within which a lower management level can act without escalation.","learningPoint":"Escalate a forecast tolerance breach, not every deviation from plan.","id":"V21-S005","concept":1005},{"topic":"Principles","subtopic":"Products","question":"A team starts scheduling activities before agreeing what the final outputs must contain or how they will be accepted. Which principle should be applied more strongly?","answer":"Focus on products","options":["Continued business justification","Manage by exception","Learn from experience","Focus on products"],"explanation":"Product focus starts with a clear definition of outputs and their quality expectations.","learningPoint":"Define products before becoming absorbed in activities.","id":"V21-S006","concept":1006},{"topic":"Principles","subtopic":"Tailoring","question":"A small internal project combines several management products into one concise document while retaining the required controls. Which principle does this demonstrate?","answer":"Tailor to suit the project","options":["Tailor to suit the project","Learn from experience","Manage by stages","Focus on products"],"explanation":"Tailoring adapts the method to the project context while preserving its principles.","learningPoint":"Tailoring is not the same as removing essential governance.","id":"V21-S007","concept":1007},{"topic":"People","subtopic":"Adoption","question":"A project delivers a new system on time, but staff continue using the old process and expected benefits are not appearing. Which aspect was most likely under-managed?","answer":"The people affected by the change and adoption of the new way of working","options":["The people affected by the change and adoption of the new way of working","Stage tolerances","Project Assurance independence","Supplier procurement"],"explanation":"Outputs create value only when the resulting change is adopted and used.","learningPoint":"Delivery of an output is not the same as realization of an outcome or benefit.","id":"V21-S008","concept":1008},{"topic":"People","subtopic":"Stakeholders","question":"A regulator has high influence over the project but has not been considered in the communication approach. What should the project do?","answer":"Assess the regulator as a stakeholder and plan appropriate engagement","options":["Ask the Team Manager to approve the regulator","Assess the regulator as a stakeholder and plan appropriate engagement","Wait until project closure","Remove the regulator from scope"],"explanation":"Stakeholder engagement should reflect influence, interest and communication needs.","learningPoint":"Communication should be tailored to stakeholder needs.","id":"V21-S009","concept":1009},{"topic":"People","subtopic":"Communication","question":"Senior users need a monthly summary while operational teams need weekly implementation updates. Where should these needs be defined?","answer":"Communication management approach","options":["Communication management approach","Issue register","Project product description","Benefits management approach"],"explanation":"The communication management approach describes how, when and with whom information will be exchanged.","learningPoint":"Different stakeholders can require different information and frequencies.","id":"V21-S010","concept":1010},{"topic":"People","subtopic":"Leadership","question":"A Project Manager has established clear controls, but the team is disengaged and resistant to the change. Which capability is particularly needed in addition to management?","answer":"Leadership","options":["Project Support","Change Authority","Leadership","Quality assurance"],"explanation":"Leadership influences and motivates people; management organizes and controls work.","learningPoint":"Projects need both leadership and management.","id":"V21-S011","concept":1011},{"topic":"Business case","subtopic":"Purpose","question":"During a stage boundary, forecast costs rise sharply and expected benefits fall. Which practice should be updated to support the decision on whether to continue?","answer":"Business case","options":["Plans","Quality","Issues","Business case"],"explanation":"The business case supports continued investment decisions throughout the project.","learningPoint":"Revisit justification when costs, risks, benefits or timescales materially change.","id":"V21-S012","concept":1012},{"topic":"Business case","subtopic":"Executive","question":"The business case needs a single Project Board member accountable for ensuring the project remains worthwhile. Who is this?","answer":"Executive","options":["Senior User","Executive","Senior Supplier","Project Manager"],"explanation":"The Executive is accountable for the business case and the business viewpoint.","learningPoint":"Executive = ultimate project accountability and business case ownership.","id":"V21-S013","concept":1013},{"topic":"Business case","subtopic":"Benefits approach","question":"Some benefits will only be measurable six months after project closure. Which management product should specify these post-project reviews?","answer":"Benefits management approach","options":["End project report","Stage plan","Issue register","Benefits management approach"],"explanation":"The benefits management approach defines how and when benefits will be measured.","learningPoint":"Benefits can be measured after closure; the approach explains how.","id":"V21-S014","concept":1014},{"topic":"Business case","subtopic":"Benefits","question":"A project delivers a new ticketing system. Staff then process passengers faster because they use it. What is the faster processing?","answer":"An outcome","options":["A management product","A dis-benefit","An outcome","An output"],"explanation":"An outcome is the result of using project outputs.","learningPoint":"Keep output → outcome → benefit separate.","id":"V21-S015","concept":1015},{"topic":"Business case","subtopic":"Loss of justification","question":"The project can still deliver its products, but the business case is no longer viable. What should the Project Board consider?","answer":"Premature closure of the project","options":["Continuing until all planned products are complete","Premature closure of the project","Increasing all tolerances","Transferring accountability to the Team Manager"],"explanation":"PRINCE2 does not support continuing a project without valid business justification.","learningPoint":"Technical deliverability does not override the need for business justification.","id":"V21-S016","concept":1016},{"topic":"Organizing","subtopic":"Project Board","question":"The Project Manager asks for authorization to start the next management stage. Which level normally makes this decision?","answer":"Project Board","options":["Project Board","Team Manager","Quality assurance","Project Support"],"explanation":"The Project Board makes key authorization decisions and directs the project.","learningPoint":"Project Board directs; Project Manager manages day to day.","id":"V21-S017","concept":1017},{"topic":"Organizing","subtopic":"Senior User","question":"Users disagree with the proposed acceptance criteria for the final product. Which Project Board role should primarily represent their interests?","answer":"Senior User","options":["Executive","Project Support","Senior Supplier","Senior User"],"explanation":"The Senior User represents user needs, acceptance interests and expected benefits.","learningPoint":"Senior User = user needs, acceptance and benefits.","id":"V21-S018","concept":1018},{"topic":"Organizing","subtopic":"Senior Supplier","question":"There is concern that the proposed solution cannot be built with the available specialist resources. Which Project Board role should lead consideration of this supplier concern?","answer":"Senior Supplier","options":["Senior Supplier","Executive","Senior User","Project Manager"],"explanation":"The Senior Supplier represents supplier interests and specialist capability.","learningPoint":"Senior Supplier = feasibility and integrity of the specialist solution.","id":"V21-S019","concept":1019},{"topic":"Organizing","subtopic":"Project Manager","question":"A work package needs to be authorized, its progress monitored, and an issue escalated to the Board. Which role normally performs these day-to-day management actions?","answer":"Project Manager","options":["Senior User","Team Manager","Executive","Project Manager"],"explanation":"The Project Manager manages the project day to day within constraints set by the Project Board.","learningPoint":"Project Manager manages; Project Board directs.","id":"V21-S020","concept":1020},{"topic":"Organizing","subtopic":"Team Manager","question":"A specialist team has accepted a work package containing three products. Who is responsible for managing delivery of those products to the agreed constraints?","answer":"Team Manager","options":["Executive","Team Manager","Senior User","Project Manager"],"explanation":"The Team Manager manages production of products in an agreed work package.","learningPoint":"Work package is the key interface between Project Manager and Team Manager.","id":"V21-S021","concept":1021},{"topic":"Organizing","subtopic":"Project Assurance","question":"The Executive wants an independent check that the business case remains sound and controls are being applied correctly. Which function provides this?","answer":"Project Assurance","options":["Project Support","Project Assurance","Change Authority","Team Manager"],"explanation":"Project Assurance gives the Project Board independent confidence that the project is being conducted properly.","learningPoint":"Assurance checks; Support assists.","id":"V21-S022","concept":1022},{"topic":"Organizing","subtopic":"Project Support","question":"The Project Manager needs help maintaining registers, arranging meetings and administering project information. Which role/function is most appropriate?","answer":"Project Support","options":["Executive","Project Support","Senior User","Project Assurance"],"explanation":"Project Support provides administrative and specialist assistance.","learningPoint":"Project Support does not take over Project Manager accountability.","id":"V21-S023","concept":1023},{"topic":"Plans","subtopic":"Purpose","question":"The Project Board wants to understand what will be delivered, by when, at what cost and with which resources. Which practice provides this basis?","answer":"Plans","options":["Plans","Business case","Quality","Progress"],"explanation":"Plans describe the means of delivering products and support communication and control.","learningPoint":"A plan is more than a schedule; it links products, activities, resources, time and cost.","id":"V21-S024","concept":1024},{"topic":"Plans","subtopic":"Product-based planning","question":"A team has listed hundreds of tasks but still cannot agree what outputs those tasks are intended to create. What should it do first?","answer":"Define the required products","options":["Delegate planning to Project Assurance","Produce an exception report","Increase time tolerance","Define the required products"],"explanation":"Product-based planning identifies and defines products before detailed activities.","learningPoint":"Products first, activities second.","id":"V21-S025","concept":1025},{"topic":"Plans","subtopic":"Project plan","question":"The Project Board needs a view of major products, costs and timescales for the whole project rather than one stage. Which plan should it use?","answer":"Project plan","options":["Stage plan","Work package","Project plan","Team plan"],"explanation":"The project plan gives the overall project-level view.","learningPoint":"Project plan = whole project; stage plan = one management stage.","id":"V21-S026","concept":1026},{"topic":"Plans","subtopic":"Stage plan","question":"The next management stage is about to be authorized. Which plan should provide sufficient detail for the Project Manager to control that stage?","answer":"Stage plan","options":["Project plan","Stage plan","Benefits management approach","Project brief"],"explanation":"Stage plans provide detailed control information for an individual management stage.","learningPoint":"A stage plan is more detailed than the project plan for the period it covers.","id":"V21-S027","concept":1027},{"topic":"Plans","subtopic":"Exception plan","question":"A stage is forecast to exceed time and cost tolerance. The Project Board asks how the remainder of the stage could be recovered. What should be produced?","answer":"Exception plan","options":["Exception report","Exception plan","Project plan","Product description"],"explanation":"An exception plan replaces a plan forecast to go into exception when requested by the higher authority.","learningPoint":"Exception report informs the decision; exception plan replaces the failed plan if requested.","id":"V21-S028","concept":1028},{"topic":"Plans","subtopic":"Project product description","question":"The customer and project team disagree about what must be true for the final project output to be accepted. Which management product should resolve this?","answer":"Project product description","options":["Stage plan","Project product description","Issue register","Highlight report"],"explanation":"The project product description defines the major final product and its acceptance criteria.","learningPoint":"Acceptance criteria for the final project product belong here.","id":"V21-S029","concept":1029},{"topic":"Plans","subtopic":"Product description","question":"A team is about to create a specialist deliverable and needs to know its quality specifications and how quality will be checked. Which product should it consult?","answer":"Product description","options":["Product description","Project brief","Risk register","End stage report"],"explanation":"A product description defines an individual product and how its quality will be assessed.","learningPoint":"Project product description is overall; product descriptions are for individual products.","id":"V21-S030","concept":1030},{"topic":"Quality","subtopic":"Purpose","question":"A product is delivered on time but does not meet the agreed quality specifications. Which practice should have provided the controls to prevent or detect this?","answer":"Quality","options":["Plans","Quality","Business case","Progress"],"explanation":"The quality practice ensures products are fit for purpose and meet requirements.","learningPoint":"On time and on budget is not enough if the product is not fit for purpose.","id":"V21-S031","concept":1031},{"topic":"Quality","subtopic":"Quality control","question":"A completed product is being inspected against its defined quality specifications before approval. What activity is taking place?","answer":"Quality control","options":["Benefits review","Quality control","Project Assurance","Risk analysis"],"explanation":"Quality control checks actual products against their agreed quality criteria.","learningPoint":"Quality control is product-focused checking.","id":"V21-S032","concept":1032},{"topic":"Quality","subtopic":"Quality assurance","question":"An organizational quality function reviews whether the project is complying with corporate quality standards. What is this?","answer":"Quality assurance","options":["Project Support","Quality assurance","Project Assurance","Quality control"],"explanation":"Quality assurance is an organizational function independent of the project management team.","learningPoint":"Quality assurance checks the quality system; quality control checks products.","id":"V21-S033","concept":1033},{"topic":"Quality","subtopic":"Quality register","question":"The Project Manager wants a record of all scheduled product reviews, who performed them and their outcomes. Which management product should be used?","answer":"Quality register","options":["Daily log","Benefits management approach","Issue register","Quality register"],"explanation":"The quality register records planned and completed quality activities and results.","learningPoint":"Think quality activity log: planned, performed, result.","id":"V21-S034","concept":1034},{"topic":"Risk","subtopic":"Definition","question":"A supplier might be unable to provide a component next month, which could delay delivery. How should this be classified now?","answer":"A risk","options":["A risk","An issue","An exception","A lesson"],"explanation":"A risk is an uncertain event that may affect objectives.","learningPoint":"If it might happen, think risk; if it has happened, think issue.","id":"V21-S035","concept":1035},{"topic":"Risk","subtopic":"Opportunity","question":"A new technology may become available earlier than expected and could reduce project cost. How should this uncertainty be classified?","answer":"An opportunity","options":["An opportunity","A threat","A dis-benefit","An issue"],"explanation":"PRINCE2 recognizes positive risks as opportunities.","learningPoint":"Risk does not mean only negative events.","id":"V21-S036","concept":1036},{"topic":"Risk","subtopic":"Risk owner","question":"A senior engineer is accountable for monitoring a supplier failure risk and deciding whether further response is required. What role is the engineer performing?","answer":"Risk owner","options":["Change Authority","Risk action owner","Risk owner","Team Manager"],"explanation":"The risk owner is accountable for management, monitoring and control of an assigned risk.","learningPoint":"Risk owner owns the risk; risk action owner performs a specific action.","id":"V21-S037","concept":1037},{"topic":"Risk","subtopic":"Risk action owner","question":"A procurement specialist is assigned to obtain an alternative supplier quotation as one response to a risk. Which role is the specialist performing?","answer":"Risk action owner","options":["Risk action owner","Project Assurance","Executive","Risk owner"],"explanation":"A risk action owner implements a specific agreed response action.","learningPoint":"One risk owner may be supported by several action owners.","id":"V21-S038","concept":1038},{"topic":"Risk","subtopic":"Avoid","question":"A project changes its design so that a hazardous component is no longer required, eliminating the related threat. Which response has been used?","answer":"Avoid","options":["Reduce","Transfer","Accept","Avoid"],"explanation":"Avoid removes the threat by changing the situation.","learningPoint":"Avoid removes the threat; reduce lowers probability or impact.","id":"V21-S039","concept":1039},{"topic":"Risk","subtopic":"Exploit","question":"A project reallocates its best engineers specifically to make certain that a cost-saving opportunity is realized. Which opportunity response is being used?","answer":"Exploit","options":["Accept","Exploit","Enhance","Share"],"explanation":"Exploit aims to ensure that an opportunity occurs.","learningPoint":"Exploit is the strongest proactive response to an opportunity.","id":"V21-S040","concept":1040},{"topic":"Risk","subtopic":"Risk register","question":"The Project Board asks for the current probability, impact, owner and response status of a supplier threat. Which record should provide this?","answer":"Risk register","options":["Issue register","Daily log","Quality register","Risk register"],"explanation":"The risk register is the primary record of identified project risks.","learningPoint":"Know which register holds which information.","id":"V21-S041","concept":1041},{"topic":"Issues","subtopic":"Issue","question":"The supplier has confirmed that a critical component will be delivered two weeks late. What is this now?","answer":"An issue","options":["A risk only","A product description","An issue","An opportunity"],"explanation":"Once an uncertain event has occurred or become current, it is managed as an issue.","learningPoint":"Risk = uncertain future; issue = current or occurred.","id":"V21-S042","concept":1042},{"topic":"Issues","subtopic":"Change control","question":"A user asks for an approved baseline product to contain an additional feature. How should this initially be classified?","answer":"A request for change","options":["An off-specification","A request for change","A lesson","A threat"],"explanation":"A request to alter an approved baseline is a request for change.","learningPoint":"Requests for change are issues and should be assessed before altering baselines.","id":"V21-S043","concept":1043},{"topic":"Issues","subtopic":"Baseline","question":"Testing shows a product cannot meet one mandatory approved specification without redesign. Which type of issue is this?","answer":"Off-specification","options":["Off-specification","Request for change","Opportunity","Exception plan"],"explanation":"An off-specification records a product that is or will be outside its approved specification.","learningPoint":"Request for change asks to alter baseline; off-specification says baseline cannot/will not be met.","id":"V21-S044","concept":1044},{"topic":"Issues","subtopic":"Change Authority","question":"The Project Board wants routine low-cost change requests decided without waiting for a full Board meeting. What should it establish?","answer":"A Change Authority with delegated limits","options":["A new Senior User","Project Assurance","A Change Authority with delegated limits","An exception plan"],"explanation":"A Change Authority can decide specified changes within delegated limits.","learningPoint":"Delegation should have clear limits, consistent with management by exception.","id":"V21-S045","concept":1045},{"topic":"Issues","subtopic":"Impact assessment","question":"A proposed change would improve quality but add cost and delay the project. What should happen before a decision is made?","answer":"Assess the overall impact on project objectives and justification","options":["Approve it because quality improves","Reject it because time increases","Ask Project Support to decide","Assess the overall impact on project objectives and justification"],"explanation":"Change decisions require a rounded impact assessment.","learningPoint":"Consider time, cost, quality, scope, benefits, risk and sustainability where relevant.","id":"V21-S046","concept":1046},{"topic":"Progress","subtopic":"Purpose","question":"The Project Manager compares actual cost and completion against the stage plan and forecasts whether tolerance will be exceeded. Which practice is being applied?","answer":"Progress","options":["Business case","Plans","Progress","Quality"],"explanation":"Progress combines monitoring, forecasting, reporting and control.","learningPoint":"PRINCE2 control is forward-looking: forecast whether tolerance will be exceeded.","id":"V21-S047","concept":1047},{"topic":"Progress","subtopic":"Tolerance","question":"A Project Manager has authority to manage a stage within ±5 days of the planned end date. What does ±5 days represent?","answer":"Time tolerance","options":["Time tolerance","Risk budget","Stage boundary","Quality method"],"explanation":"Tolerance establishes delegated limits of authority.","learningPoint":"Tolerance can apply to time, cost, quality, scope, benefits, risk and sustainability.","id":"V21-S048","concept":1048},{"topic":"Progress","subtopic":"Exception","question":"Current stage cost is still within tolerance, but the forecast shows it will exceed tolerance before stage end. What should the Project Manager do?","answer":"Escalate with an exception report","options":["Wait until the overspend actually occurs","Escalate with an exception report","Increase the tolerance","Rewrite the business case without informing the Board"],"explanation":"PRINCE2 escalates on a forecast tolerance breach.","learningPoint":"Forecast breach = exception report; do not wait for the breach to happen.","id":"V21-S049","concept":1049},{"topic":"Progress","subtopic":"Highlight report","question":"The Project Board has asked for a concise status update every two weeks while the stage proceeds normally. Which report should the Project Manager provide?","answer":"Highlight report","options":["Checkpoint report","End stage report","Highlight report","Exception report"],"explanation":"Highlight reports are regular Project Manager-to-Project Board status reports.","learningPoint":"Highlight = PM to Board; Checkpoint = Team Manager to PM.","id":"V21-S050","concept":1050},{"topic":"Progress","subtopic":"Checkpoint report","question":"A delivery team reports weekly progress on its work package to the Project Manager. What report should normally be used?","answer":"Checkpoint report","options":["End project report","Highlight report","Exception report","Checkpoint report"],"explanation":"Checkpoint reports are regular team-level progress reports.","learningPoint":"Checkpoint = Team Manager to Project Manager.","id":"V21-S051","concept":1051},{"topic":"Progress","subtopic":"End stage report","question":"The Project Board is deciding whether to authorize the next stage and wants to know how the current stage performed. Which report should it review?","answer":"End stage report","options":["Checkpoint report","End stage report","Issue report","Highlight report"],"explanation":"The end stage report summarizes actual performance of the current management stage.","learningPoint":"Stage-end decision uses current performance plus next-stage and updated justification information.","id":"V21-S052","concept":1052},{"topic":"Processes","subtopic":"Starting up a Project","question":"A new idea has been proposed but the organization wants a lightweight check before committing resources to full initiation. Which process should be used?","answer":"Starting up a Project","options":["Managing Product Delivery","Initiating a Project","Starting up a Project","Directing a Project"],"explanation":"Starting up a Project checks whether there is a viable and worthwhile project before full initiation.","learningPoint":"Starting up is pre-project; initiating establishes the detailed management foundations.","id":"V21-S053","concept":1053},{"topic":"Processes","subtopic":"Directing a Project","question":"A decision is required to authorize initiation after the project brief has been reviewed. Which process contains this Project Board decision?","answer":"Directing a Project","options":["Controlling a Stage","Starting up a Project","Directing a Project","Managing a Stage Boundary"],"explanation":"Directing a Project is the Board-level process for key authorization and direction decisions.","learningPoint":"Board-level authorizations sit in Directing a Project.","id":"V21-S054","concept":1054},{"topic":"Processes","subtopic":"Initiating a Project","question":"The Project Board has authorized initiation. Detailed management approaches, controls and the project plan now need to be established. Which process does this?","answer":"Initiating a Project","options":["Closing a Project","Managing Product Delivery","Starting up a Project","Initiating a Project"],"explanation":"Initiating a Project creates the detailed management foundations and PID.","learningPoint":"Starting up is preliminary; initiating defines how the project will be managed.","id":"V21-S055","concept":1055},{"topic":"Processes","subtopic":"Controlling a Stage","question":"A stage is underway. The Project Manager reviews status, authorizes a work package and handles an issue. Which process is being used?","answer":"Controlling a Stage","options":["Managing a Stage Boundary","Directing a Project","Managing Product Delivery","Controlling a Stage"],"explanation":"Controlling a Stage is the Project Manager’s day-to-day control process for an authorized stage.","learningPoint":"Project Manager uses Controlling a Stage while Team Manager uses Managing Product Delivery.","id":"V21-S056","concept":1056},{"topic":"Processes","subtopic":"Managing Product Delivery","question":"A Team Manager agrees a work package, oversees creation of its products and reports completion back to the Project Manager. Which process is being used?","answer":"Managing Product Delivery","options":["Closing a Project","Managing Product Delivery","Directing a Project","Controlling a Stage"],"explanation":"Managing Product Delivery is the team-side process for accepting, executing and delivering work packages.","learningPoint":"Think work package lifecycle from the Team Manager’s perspective.","id":"V21-S057","concept":1057},{"topic":"Processes","subtopic":"Managing a Stage Boundary","question":"The current stage is almost complete. The Project Manager updates the business case, prepares the next stage plan and reports stage performance. Which process is this?","answer":"Managing a Stage Boundary","options":["Controlling a Stage","Managing a Stage Boundary","Closing a Project","Starting up a Project"],"explanation":"Managing a Stage Boundary supports the Project Board’s end-stage decision.","learningPoint":"At a boundary: review current stage, update justification, plan next stage.","id":"V21-S058","concept":1058},{"topic":"Processes","subtopic":"Closing a Project","question":"The final product has been accepted and the Project Manager is evaluating performance and preparing recommendations for follow-on action. Which process is being used?","answer":"Closing a Project","options":["Directing a Project","Controlling a Stage","Managing a Stage Boundary","Closing a Project"],"explanation":"Closing a Project provides orderly acceptance, evaluation, handover and closure.","learningPoint":"PRINCE2 also uses this process for controlled premature closure.","id":"V21-S059","concept":1059},{"topic":"Sustainability","subtopic":"Performance","question":"A cheaper delivery option would materially increase environmental impact beyond an agreed sustainability tolerance. How should this be treated?","answer":"As a project performance deviation that may require escalation if tolerance is forecast to be exceeded","options":["As quality assurance only","As irrelevant because cost is lower","As a project performance deviation that may require escalation if tolerance is forecast to be exceeded","As a mandatory opportunity"],"explanation":"PRINCE2 7 explicitly incorporates sustainability into project performance considerations.","learningPoint":"Sustainability can be planned, monitored and subject to tolerance.","id":"V21-S060","concept":1060},{"topic":"Digital and data","subtopic":"Approach","question":"A project will use sensitive operational data from several systems. Where should principles for access, storage, quality and use of that data be defined?","answer":"Digital and data management approach","options":["Benefits management approach","Issue report","Digital and data management approach","Quality register"],"explanation":"The digital and data management approach defines how project data and digital information will be managed.","learningPoint":"Good decisions depend on trustworthy and appropriately governed data.","id":"V21-S061","concept":1061},{"topic":"Tailoring","subtopic":"Small project","question":"A low-risk two-month project uses the same PRINCE2 principles as a major project but much lighter documentation and fewer formal meetings. Is this consistent with PRINCE2?","answer":"Yes, if the tailoring preserves necessary responsibilities and controls","options":["No, every project must use identical documentation","Yes, but only if all tolerances are removed","Yes, if the tailoring preserves necessary responsibilities and controls","No, small projects cannot use PRINCE2"],"explanation":"Tailoring adapts formality and detail to context without abandoning governance.","learningPoint":"Tailor the method, not the integrity of its principles and controls.","id":"V21-S062","concept":1062}]};